templates.time_series_batch:
{% for (name, series), signal in time_series|zip(signals) %}
select {{name | sql_literal}} as name, * from (
{%- if subsampled -%}
  {%- if signal.datatype == 'number' and (timestamp_stop - timestamp_start) >= (resolution * 2**(dataset.get("layer_shift", 32)|int)) -%}
    with time_series as ( -- layer1 buckets
      select
        width_bucket(
          time + (1::bigint<<{{ (dataset.get("layer_shift", 32)|int) - 1 }}),
          {{ timestamp_start }},
          {{ timestamp_stop }},
          {{ resolution }}
        ) as time_bucket,
        min(min_value) as low_bound,
        max(max_value) as up_bound
      from "mdb_data"."mdb_{{datapool}}_layer1_{{dataset.dataset}}_{{signal.metadata.id}}"
      where {{ timestamp_start }} <= time
        and {{ timestamp_stop }} >= time
      group by time_bucket
    )
  {%- else -%}
    with time_series as ( -- raw buckets
      select
        width_bucket(
          "timestamp",
          {{ timestamp_start }},
          {{ timestamp_stop }},
          {{ resolution }}
        ) as time_bucket,
        min(value) as low_bound,
        max(value) as up_bound
      from ({{ series }}) as series
      group by time_bucket
    )
  {% endif %}
select
  ({{timestamp_stop}} - {{timestamp_start}}) / {{resolution}} * (n-1) + {{timestamp_start}} as "timestamp",
  time_series.low_bound,
  time_series.up_bound
from generate_series(1, {{resolution}}) as range(n) -- insert empty buckets
left join time_series
  on range.n = time_series.time_bucket
{%- else -%}
{{ series }} -- raw data
{%- endif %}
) as data
order by "timestamp" asc;
{% endfor %}

templates.time_series:
select
  time as "timestamp",
  {{ 'value_text' if signal.datatype == 'text' else 'value' }} as value
from mdb_{{datapool}}_data(
    {{dataset.dataset}},
    {{signal.metadata.id}},
    {{ timestamp_start | int if timestamp_start is not none and timestamp_start != '' else 'NULL' }},
    {{ timestamp_stop | int if timestamp_stop is not none and timestamp_stop != '' else 'NULL' }}
)

templates.metric_dataset:
{% for signal in signals -%}
    {% if agg == "count" %}
        SELECT {{ index }} as index, count as metric
        from "public"."mdb_{{datapool}}_signal"
        where dataset_id = {{dataset.dataset}}
        and signal_id = {{signal.metadata.id}}
    {% else %}
        {% set stat = "mean" if agg == "avg" else agg %}
        SELECT {{ index }} as index, (stats->>'{{stat}}')::float as metric
        from "public"."mdb_{{datapool}}_signal"
        where dataset_id = {{dataset.dataset}}
        and signal_id = {{signal.metadata.id}}
    {% endif %}
{% endfor %}
